package com.mushafi.app;
import android.app.*;import android.content.*;import android.media.*;import org.json.*;import java.lang.reflect.*;import java.util.concurrent.atomic.*;
public final class LargeSeekChecks {
 interface Check{boolean get()throws Exception;}static void until(Check c)throws Exception{long end=System.currentTimeMillis()+60000;while(System.currentTimeMillis()<end){if(c.get())return;Thread.sleep(100);}throw new Exception("long-seek timeout");}static void need(boolean b,String s)throws Exception{if(!b)throw new Exception(s);}static JSONObject state(SurahPlaybackService s)throws Exception{return new JSONObject(s.snapshot());}static void field(Object target,String key,Object value)throws Exception{Field f=target.getClass().getDeclaredField(key);f.setAccessible(true);f.set(target,value);}static Object field(Object target,String key)throws Exception{Field f=target.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(target);}static String key(JSONArray times,int position){String key="";for(int n=0;n<times.length();n++){JSONArray r=times.optJSONArray(n);if(r.optInt(1)>position)break;key="2:"+r.optInt(0);}return key;}
 public static void run(Instrumentation t)throws Exception{
  MainActivity a=(MainActivity)t.startActivitySync(new Intent(t.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));until(()->field(a,"surahService")!=null);SurahPlaybackService s=(SurahPlaybackService)field(a,"surahService");JSONObject catalog=(JSONObject)field(s,"catalog");JSONArray times=catalog.getJSONObject("7").getJSONObject("chapters").getJSONObject("2").getJSONArray("timings");MediaPlayer[] box=new MediaPlayer[1];AtomicBoolean ready=new AtomicBoolean();AtomicReference<String> error=new AtomicReference<>();Method complete=s.getClass().getDeclaredMethod("completeSeek",MediaPlayer.class);complete.setAccessible(true);
  t.runOnMainSync(()->{try{s.stop();MediaPlayer mp=new MediaPlayer();box[0]=mp;mp.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());mp.setOnSeekCompleteListener(p->{try{complete.invoke(s,p);}catch(Exception e){error.set(e.toString());}});mp.setOnErrorListener((p,w,e)->{error.set("MediaPlayer "+w+"/"+e);return true;});mp.setOnPreparedListener(p->{try{field(s,"player",p);field(s,"reader",7);field(s,"chapter",2);field(s,"timings",times);field(s,"position",0);field(s,"duration",p.getDuration());field(s,"prepared",true);field(s,"status","playing");p.start();ready.set(true);s.seek(60000,"minute-1");}catch(Exception e){error.set(e.toString());}});mp.setDataSource("http://10.0.2.2:8768/long.mp3");mp.prepareAsync();}catch(Exception e){error.set(e.toString());}});
  try{until(()->error.get()!=null||(ready.get()&&!state(s).optBoolean("seeking")&&"minute-1".equals(state(s).optString("seekToken"))));need(error.get()==null,String.valueOf(error.get()));need(state(s).optInt("duration")>1200000,"real long file duration");
   t.runOnMainSync(()->s.seek(900000,"minute-15"));until(()->error.get()!=null||(!state(s).optBoolean("seeking")&&"minute-15".equals(state(s).optString("seekToken"))));need(error.get()==null,String.valueOf(error.get()));JSONObject first=state(s);need(Math.abs(first.optInt("position")-900000)<2000,"15-minute actual audio position");need(first.optString("key").equals(key(times,first.optInt("position"))),"15-minute actual ayah");need(field(s,"player")==box[0],"same continuous source");
   t.runOnMainSync(()->{s.seek(1200000,"older-20");s.seek(120000,"older-2");s.seek(900000,"latest-15");});need("latest-15".equals(state(s).optString("seekToken"))&&state(s).optInt("seekPosition")==900000,"latest intent published immediately during in-flight seek");until(()->error.get()!=null||(!state(s).optBoolean("seeking")&&"latest-15".equals(state(s).optString("seekToken"))));need(error.get()==null,String.valueOf(error.get()));need(Math.abs(state(s).optInt("position")-900000)<2000,"rapid streamed seeks finish at last target");
   t.runOnMainSync(()->{s.pause();s.seek(300000,"paused-5");});until(()->!state(s).optBoolean("seeking")&&"paused-5".equals(state(s).optString("seekToken")));need("paused".equals(state(s).optString("status")),"paused scrub stays paused");need(state(s).optString("key").equals(key(times,state(s).optInt("position"))),"paused seek actual ayah");need(field(s,"player")==box[0],"no duplicate streamed player");
  }finally{t.runOnMainSync(()->{s.stop();if(box[0]!=null)try{box[0].release();}catch(Exception ignored){}});}
 }
}
